//! Shared by `vectors.rs`, `vectors2.rs` and `gen_standin_vectors.rs`.
//!
//! # Which vectors run
//!
//! The vector tests read two JSON files, `geb-path-b-vectors.json` and
//! `geb-path-b-vectors-2.json`. Two sets exist:
//!
//! - **Stand-in vectors**, committed in `tests/fixtures/`. Generated by this crate's
//!   own code from fresh throwaway keys (`gen_standin_vectors.rs`). They prove that the
//!   crate agrees with itself and that the fixture structure is what the tests expect.
//!   They do NOT prove agreement with Geb: every expected output in them was computed
//!   by this crate.
//! - **Geb's real files** (outputs of Geb's own code), which are not redistributed with
//!   this repository. When present they are used instead, and they are the real interop
//!   check. They are looked up in `$GEB_VECTORS_DIR` if set (a missing file there is an
//!   error), else in `tests/fixtures/private/` (git-ignored). `GEB_VECTORS_REQUIRE_REAL=1`
//!   makes a missing real file an error rather than a fall back to the stand-in.
//!
//! Each loaded file is announced on stdout (`cargo test -- --nocapture`), and
//! `vectors2::which_vectors_ran` always names the set.
#![allow(dead_code, clippy::unwrap_used, clippy::expect_used)]

use hkdf::Hkdf;
use serde_json::Value;
use sha2::{Digest, Sha256};
use std::path::{Path, PathBuf};

pub const V1: &str = "geb-path-b-vectors.json";
pub const V2: &str = "geb-path-b-vectors-2.json";

/// Where a fixture file came from.
#[derive(Debug, Clone, PartialEq)]
pub enum Source {
    Real(PathBuf),
    StandIn(PathBuf),
}

fn fixtures_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures")
}

/// Resolve `name` to a real Geb file when one is available, else the stand-in.
pub fn resolve(name: &str) -> Source {
    let explicit = std::env::var_os("GEB_VECTORS_DIR").map(PathBuf::from);
    let require = std::env::var_os("GEB_VECTORS_REQUIRE_REAL").is_some();
    let dir = explicit
        .clone()
        .unwrap_or_else(|| fixtures_dir().join("private"));
    let real = dir.join(name);
    if real.is_file() {
        return Source::Real(real);
    }
    assert!(
        explicit.is_none() && !require,
        "real Geb vectors were required (GEB_VECTORS_DIR / GEB_VECTORS_REQUIRE_REAL) but {} does not exist",
        real.display()
    );
    Source::StandIn(fixtures_dir().join(name))
}

/// The text of fixture `name`, announcing which set it is.
pub fn load(name: &str) -> String {
    let src = resolve(name);
    match &src {
        Source::Real(p) => println!("vectors: {name}: REAL Geb file {}", p.display()),
        Source::StandIn(p) => println!(
            "vectors: {name}: STAND-IN (self-consistency only, not agreement with Geb) {}",
            p.display()
        ),
    }
    let (Source::Real(p) | Source::StandIn(p)) = src;
    std::fs::read_to_string(&p).unwrap_or_else(|e| panic!("read {}: {e}", p.display()))
}

pub fn jcs(v: &Value) -> Vec<u8> {
    serde_json_canonicalizer::to_vec(v).unwrap()
}

/// RFC 9420 section 8 `ExpandWithLabel` with SHA-256, written out here from
/// the RFC, independent of OpenMLS. KDFLabel = length(u16) || opaque<V> label
/// ("MLS 1.0 " + label) || opaque<V> context, with the one-byte varint length
/// used for anything under 64 bytes.
pub fn expand_with_label(secret: &[u8], label: &str, context: &[u8], len: u16) -> Vec<u8> {
    let full = format!("MLS 1.0 {label}");
    assert!(full.len() < 64 && context.len() < 64);
    let mut info = len.to_be_bytes().to_vec();
    info.push(full.len() as u8);
    info.extend_from_slice(full.as_bytes());
    info.push(context.len() as u8);
    info.extend_from_slice(context);
    let mut out = vec![0u8; len as usize];
    Hkdf::<Sha256>::from_prk(secret)
        .unwrap()
        .expand(&info, &mut out)
        .unwrap();
    out
}

/// RFC 9420 section 8.5 `MLS-Exporter`.
pub fn mls_exporter(exporter_secret: &[u8], label: &str, context: &[u8], len: u16) -> Vec<u8> {
    let derived = expand_with_label(exporter_secret, label, b"", 32);
    expand_with_label(&derived, "exported", &Sha256::digest(context), len)
}

/// Seconds since the epoch of `YYYY-MM-DDTHH:MM:SSZ` (days from civil, Hinnant).
pub fn iso_secs(iso: &str) -> u64 {
    let t = iso.strip_suffix('Z').unwrap();
    let (d, tm) = t.split_once('T').unwrap();
    let d: Vec<i64> = d.split('-').map(|x| x.parse().unwrap()).collect();
    let tm: Vec<i64> = tm.split(':').map(|x| x.parse().unwrap()).collect();
    let (y, m) = if d[1] <= 2 {
        (d[0] - 1, d[1] + 9)
    } else {
        (d[0], d[1] - 3)
    };
    let era = y.div_euclid(400);
    let yoe = y - era * 400;
    let doy = (153 * m + 2) / 5 + d[2] - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    ((era * 146_097 + doe - 719_468) * 86_400 + tm[0] * 3600 + tm[1] * 60 + tm[2]) as u64
}
